#!/bin/sh
# SPDX-License-Identifier: GPL-2.0
# Lab 14 acceptance tests.  The blobs are generated by "make" (tools/mkcal.py).
. /lab/common/lib.sh
cd "$(dirname "$0")/.." || exit 1
S=/sys/class/misc/lfdcal
FW=$(pwd)/firmware
rmmod lfdcal 2>/dev/null
dmesg_reset
check "test blobs exist (run make on the host)" test -f $FW/lfd430/cal.bin
# Search our firmware directory first (the default is /lib/firmware).
echo -n "$FW" > /sys/module/firmware_class/parameters/path

conv() { echo "$1" > $S/convert && cat $S/convert; }
st() { cat $S/status; }
load() { echo "$1" > $S/fw_name; echo "$2" > $S/reload; wait_until 10 sh -c "! grep -q state=loading $S/status"; }

check "lfdcal loads" insmod ./lfdcal.ko
check_grep "the default blob was loaded at init" "state=loaded err=0 version=1 entries=5" st
check_grep "convert(0) = 100"      "^100$"  conv 0
check_grep "convert(1500) = 1700"  "^1700$" conv 1500
check_grep "convert(4095) = 5000"  "^5000$" conv 4095
check_grep "convert(9999) clamps to 5000" "^5000$" conv 9999

for b in bad-magic bad-version bad-crc truncated huge-count unsorted; do
	load lfd430/$b.bin sync
	check_grep "$b.bin rejected with -EINVAL, old table kept" "err=-22 version=1 entries=5" st
done
# The loader itself refuses empty files (fs/kernel_read_file.c), tries the
# next search path, and finally reports -ENOENT: the driver never sees it.
load lfd430/empty.bin sync
check_grep "an empty file never reaches the driver (-ENOENT)" "err=-2 version=1 entries=5" st
check_grep "conversion unchanged after the rejects" "^1700$" conv 1500
load lfd430/missing.bin sync
check_grep "a missing blob gives -ENOENT" "err=-2 " st

load lfd430/cal-v2.bin async
check_grep "async load of cal-v2.bin" "state=loaded err=0 version=1 entries=2" st
check_grep "new table in use: convert(4095) = 8190" "^8190$" conv 4095

echo lfd430/via-sysfs.bin > $S/fw_name
echo user > $S/reload
F=/sys/class/firmware/lfd430!via-sysfs.bin
check "sysfs fallback directory appears" wait_until 10 test -e "$F/loading"
check "load the blob by hand through the fallback interface" \
	sh -c "echo 1 > '$F/loading' && cat $FW/lfd430/cal.bin > '$F/data' && echo 0 > '$F/loading'"
wait_until 10 sh -c "! grep -q state=loading $S/status"
check_grep "the hand-fed blob was accepted" "state=loaded err=0 version=1 entries=5" st
check_fail "rejects path traversal in fw_name" sh -c "echo ../../etc/passwd > $S/fw_name"
check "lfdcal unloads" unload lfdcal
check_clean_log all
summary
